package server

import "testing"

// An ordinary property on a :root rule colours the page as surely as one on html
// (and outranks it), and a literal there stays put when the scheme flips: it is a
// colour outside the token table like any other, and the lint has to say so.
func TestStylesheetLintSeesALiteralOnRoot(t *testing.T) {
	for _, css := range []string{
		":root { color-scheme: light dark; }\n:root { --bg: light-dark(#ffffff, #131416); color: black; }",
		":root { color-scheme: light dark; background-color: #ffffff; }\n:root { --bg: light-dark(#ffffff, #131416); }",
	} {
		found := false
		codes := codesOf(lintStylesheet(css))
		for _, c := range codes {
			if c == "colour-literal" {
				found = true
			}
		}
		if !found {
			t.Errorf("%q: lint says %v, want a colour-literal finding", css, codes)
		}
	}
}

