package server

import "testing"

// A rule that holds a nested rule (CSS nesting, which Chrome applies) keeps its own
// declarations: the ones before the nested block and the ones after it still paint.
// The lint has to read them, or anything written beside a nested rule is unchecked.
func TestLintReadsDeclarationsBesideANestedRule(t *testing.T) {
	for _, css := range []string{
		"main.reader { opacity: .5; & > h1 { margin: 0; } }",
		"main.reader { & > h1 { margin: 0; } filter: invert(1); }",
		".badge { color: white; &:hover { margin: 0; } }",
	} {
		if got := lintStylesheet(corpusPrelude + css); len(got) == 0 {
			t.Errorf("lintStylesheet says nothing about %q, whose outer declaration Chrome applies", css)
		}
	}
}

